const http = require('http');

function sendWebhook(path, data) {
  return new Promise((resolve) => {
    try {
      const payload = JSON.stringify(data);
      const req = http.request({
        hostname: '127.0.0.1',
        port: 5678,
        path: path,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(payload)
        }
      }, (res) => resolve(res.statusCode));
      req.on('error', (err) => resolve(500));
      req.write(payload);
      req.end();
    } catch(e) {
      resolve(500);
    }
  });
}

const packet = $input.first().json;
const dept = String(packet.department_code || packet.department || '').toUpperCase();

let targetRoute = '';
let targetStatus = 200;

if (dept === 'TECH') {
  targetRoute = '/webhook/ticket-dispatch';
  targetStatus = await sendWebhook('/webhook/ticket-dispatch', packet);
  await sendWebhook('/webhook/m1-flow3-ticket', packet);
} else if (dept === 'SALES') {
  targetRoute = '/webhook/crm-lead';
  targetStatus = await sendWebhook('/webhook/crm-lead', packet);
  await sendWebhook('/webhook/m3-flow7-crm-lead', packet);
} else if (dept === 'FINANCE') {
  targetRoute = '/webhook/invoice-ocr';
  targetStatus = await sendWebhook('/webhook/invoice-ocr', packet);
  await sendWebhook('/webhook/m3-flow9-invoice-ocr', packet);
} else {
  targetRoute = 'GENERAL_QUEUE';
}

return [{
  json: {
    status: 'ROUTED',
    department: dept,
    target_route: targetRoute,
    http_status: targetStatus,
    payload: packet,
    timestamp: new Date().toISOString()
  }
}];
